(function(){
 window.Malsseum.createGratitudeScreen=function({element,mainContent,localToday,dateFromKey,localDateKey,backButton}){
 const journal=window.Malsseum.services.gratitudeJournal;
 const root=element('section','gratitude-screen');root.id='gratitude-screen';root.hidden=true;root.setAttribute('aria-label','감사 기록');mainContent.append(root);
 let selected=localToday(),month=dateFromKey(selected),mode='main';
 const fields=[['today','오늘의 감사','오늘 나의 마음을 따뜻하게 한 일은 무엇인가요?'],['self','나에게 감사','오늘 나 스스로에게 고마운 일은 무엇인가요?'],['grace','하나님께 감사','오늘 하나님의 은혜로 느껴진 것은 무엇인가요?']];
 const dateLabel=d=>new Intl.DateTimeFormat('ko-KR',{month:'long',day:'numeric',weekday:'short'}).format(dateFromKey(d));
 const button=(text,cls,fn)=>{const b=element('button',cls,text);b.type='button';b.addEventListener('click',fn);return b;};
 function top(){mainContent.scrollTop=0;window.scrollTo(0,0);root.querySelector('h1')?.focus({preventScroll:true});}
 function heading(a,b,copy){const h=element('div','prayer-heading'),title=element('h1','',a);title.tabIndex=-1;if(b)title.append(document.createElement('br'),document.createTextNode(b));h.append(title,element('p','prayer-intro',copy));root.append(h);}
 function render(){root.classList.toggle('is-editor',mode==='editor');root.replaceChildren();if(mode==='editor')return editor();heading('오늘도,','감사를 기억해요','하루 속 지나치기 쉬운 감사를 떠올려보세요.');root.querySelector('h1').dataset.tabHeadline='';window.dispatchEvent(new Event('profile-headline-refresh'));let entries;try{entries=journal.list();}catch{root.append(element('p','error','감사 기록을 읽지 못했어요. 브라우저 저장 설정을 확인해주세요.'));return;}
 const calendar=element('section','prayer-calendar');calendar.setAttribute('aria-label','감사 기록 달력');const controls=element('div','prayer-calendar-controls');const prev=button('‹','calendar-nav',()=>{month=new Date(month.getFullYear(),month.getMonth()-1,1);render();}),next=button('›','calendar-nav',()=>{month=new Date(month.getFullYear(),month.getMonth()+1,1);render();});prev.setAttribute('aria-label','이전 달');next.setAttribute('aria-label','다음 달');controls.append(prev,element('h2','calendar-month',month.getFullYear()+'년 '+(month.getMonth()+1)+'월'),next);const weekdays=element('div','calendar-weekdays');for(const d of ['일','월','화','수','목','금','토'])weekdays.append(element('span','',d));const grid=element('div','calendar-grid'),y=month.getFullYear(),m=month.getMonth(),first=new Date(y,m,1),start=new Date(y,m,1-first.getDay()),count=first.getDay()+new Date(y,m+1,0).getDate()<=35?35:42;
 for(let i=0;i<count;i++){const d=new Date(start.getFullYear(),start.getMonth(),start.getDate()+i),key=localDateKey(d),has=entries.some(e=>e.date===key),b=button('','calendar-day',()=>{selected=key;month=dateFromKey(key);render();});b.dataset.date=key;b.setAttribute('aria-label',key+(has?', 감사 기록 있음':''));b.setAttribute('aria-pressed',String(selected===key));if(d.getMonth()!==m)b.classList.add('other-month');if(key===localToday()){b.classList.add('is-today');b.setAttribute('aria-current','date');}if(key===selected)b.classList.add('is-selected');b.append(element('span','calendar-day-number',String(d.getDate())));const marks=element('span','calendar-day-marks');marks.setAttribute('aria-hidden','true');if(has)marks.append(element('span','gratitude-heart','♥'));b.append(marks);grid.append(b);}
 const legend=element('div','prayer-calendar-legend'),label=element('span','','감사를 기록한 날');label.prepend(element('i','gratitude-heart','♥'));legend.append(label);calendar.append(controls,weekdays,grid,legend);root.append(calendar);
 const day=element('section','prayer-day');day.setAttribute('aria-live','polite');const title=element('div','prayer-day-heading');title.append(element('h2','',dateLabel(selected)));if(selected===localToday())title.append(element('span','today-label','오늘'));day.append(title);const record=entries.find(e=>e.date===selected);
 if(record){for(const [i,[field,name]]of fields.entries())if(record[field].trim()){const card=element('div','gratitude-entry');const entryHeading=element('div','gratitude-entry-heading');entryHeading.append(element('h3','',String(i+1).padStart(2,'0')+' '+name));card.append(entryHeading,element('p','',record[field]));day.append(card);}day.append(button('수정하기','gratitude-edit',()=>{mode='editor';render();top();}));}
 else{const empty=element('div','prayer-day-empty');empty.append(element('p','prayer-empty-title',selected===localToday()?'오늘의 감사를 남겨보세요.':'이날의 감사를 남겨보세요.'),element('p','prayer-empty-copy','한 줄의 감사도 충분해요.'),button('감사 기록하기','gratitude-cta prayer-record-button button-primary',()=>{mode='editor';render();top();}));day.append(empty);}root.append(day);
 }
 function editor(){root.append(backButton('감사 달력 보기',()=>{mode='main';render();top();}));let record;try{record=journal.list().find(e=>e.date===selected)||{};}catch{root.append(element('p','error','감사 기록을 읽지 못했어요.'));return;}
 const form=element('form','gratitude-form'),inputs={};for(const [i,[field,name,prompt]]of fields.entries()){const card=element('div','gratitude-input-card'),label=element('label','',String(i+1).padStart(2,'0')+' '+name),help=element('p','',prompt),input=element('textarea','');input.id='gratitude-'+field;label.htmlFor=input.id;help.id=input.id+'-help';input.setAttribute('aria-describedby',help.id);input.rows=2;input.value=record[field]||'';input.placeholder=['예) 따뜻한 커피 한 잔이 좋았어요.','예) 오늘도 포기하지 않고 해냈어요.','예) 오늘도 함께해 주셔서 감사해요.'][i];inputs[field]=input;card.append(label,help,input);form.append(card);}
 const status=element('p','meditation-journal-status is-saved');status.setAttribute('role','status');let saved=false;
 const saveLabel=()=>record.date?'감사 수정하기':selected===localToday()?'오늘의 감사 남기기':'이날의 감사 남기기';
 const save=element('button','gratitude-cta prayer-record-button button-primary',saveLabel());save.type='submit';form.append(status,save);
 form.addEventListener('input',()=>{if(saved){saved=false;status.textContent='';save.textContent=saveLabel();}else if(fields.some(([f])=>inputs[f].value.trim()))status.textContent='';});
 form.addEventListener('submit',event=>{event.preventDefault();if(saved){month=dateFromKey(selected);mode='main';render();top();return;}try{const editing=Boolean(record.date);record=journal.save(selected,Object.fromEntries(fields.map(([f])=>[f,inputs[f].value])));saved=true;status.textContent=editing?'감사를 수정했어요.':'감사를 남겼어요.';save.textContent='감사 달력 보기';}catch(e){status.textContent=e.message||'저장하지 못했어요. 다시 시도해주세요.';}});root.append(form);}

 window.addEventListener('storage',e=>{if(e.key===journal.key&&mode==='main')render();});
 return {root,open(){mode='main';selected=localToday();month=dateFromKey(selected);render();}};
 };
})();
